import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.4s5LDCII.js";const _=JSON.parse('{"title":"营养健康食堂建设指南","description":"国家卫健委《营养健康食堂建设指南》要点导读：单位食堂营养健康化建设与配餐要求。","frontmatter":{"title":"营养健康食堂建设指南","issuer":"国家卫生健康委办公厅","source_tier":"一级来源","version":"2020年印发","published":"2020-12","document_no":null,"source_url":"https://www.chinanutri.cn/fgbz/fgbzjszn/202012/t20201214_223263.html","status":"现行","tags":["食堂","营养健康","团餐","建设指南"],"reviewed":false,"description":"国家卫健委《营养健康食堂建设指南》要点导读：单位食堂营养健康化建设与配餐要求。"},"headers":[],"relativePath":"guides/canteen-guide-2020.md","filePath":"guides/canteen-guide-2020.md"}'),i={name:"guides/canteen-guide-2020.md"};function n(d,t,l,s,c,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="营养健康食堂建设指南" tabindex="-1">营养健康食堂建设指南 <a class="header-anchor" href="#营养健康食堂建设指南" aria-label="Permalink to &quot;营养健康食堂建设指南&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本导读由 AI 起草，尚未逐条对照原文校验；一切以原文为准。</p></div><blockquote><p><strong>原文出处</strong>：国家卫生健康委办公厅印发（<a href="https://www.chinanutri.cn/fgbz/fgbzjszn/202012/t20201214_223263.html" target="_blank" rel="noreferrer">中国疾控中心营养与健康所收录页</a>）· 一级来源</p></blockquote><h2 id="这份文件适合谁" tabindex="-1">这份文件适合谁 <a class="header-anchor" href="#这份文件适合谁" aria-label="Permalink to &quot;这份文件适合谁&quot;">​</a></h2><p>单位、学校、养老机构等集体食堂的建设者与管理者，以及在食堂吃饭、想知道&quot;什么样的食堂算营养健康&quot;的每个人。</p><h2 id="关键要点-摘要" tabindex="-1">关键要点（摘要） <a class="header-anchor" href="#关键要点-摘要" aria-label="Permalink to &quot;关键要点（摘要）&quot;">​</a></h2><ul><li>食堂在<strong>配餐结构、菜品营养标识、健康烹饪、减盐减油减糖</strong>等方面的建设要求。</li><li>鼓励食堂提供标识清晰的菜品信息，帮助就餐者自我搭配。</li><li>与《餐饮食品营养标识指南》《营养健康餐厅建设指南》同批印发、配套使用。</li></ul><h2 id="怎么用这份文件" tabindex="-1">怎么用这份文件 <a class="header-anchor" href="#怎么用这份文件" aria-label="Permalink to &quot;怎么用这份文件&quot;">​</a></h2><p>食堂管理者按指南对照改造；就餐者可以拿它当&quot;验收单&quot;，看看自己单位食堂做到了几条。具体以原文为准。</p><h2 id="溯源信息" tabindex="-1">溯源信息 <a class="header-anchor" href="#溯源信息" aria-label="Permalink to &quot;溯源信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>发布机构</td><td>国家卫生健康委办公厅</td></tr><tr><td>版本</td><td>2020 年印发（现行）</td></tr><tr><td>发布时间</td><td>2020 年 12 月</td></tr><tr><td>发文字号</td><td>待核对（见原文）</td></tr></tbody></table>',11)])])}const b=e(i,[["render",n]]);export{_ as __pageData,b as default};
